<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lamem_pt_wrapper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(melting_rule, markers, cells, step, scaling)</span></span>
